mapper.select:
select count(url)
from `av_event_log_local`
where url like #{likeURL} and found_time >= #{effectiveTime}

select client_ip, server_ip, url, found_time
from `av_event_log_local`
where url like #{likeURL}
order by found_time desc
limit #{rawLimit}

select client_ip, server_ip, url, found_time
from `av_event_log_local`
where found_time >= #{taskTime}
